breakaway.to:
u.morale -= 5;
if (window.__ev) window.__ev('Breakaway', u, null, 0);
logEv(`${u.label} 脫離接戰`, u.side);

broken.to:
u.morale = Math.min(u.morale, 25);
if (window.__ev) window.__ev('Broken', u, null, parts);
logEv(`${u.label} ${reason === '破陣' ? '陣腳被衝破，' : ''}崩潰${parts > 1 ? '，散作' + '兩三'[parts-2] + '股' : ''}`, u.side === 'ming' ? 'jp' : 'ming', true);

momentum.to:
v.momentum = Math.min(3, v.momentum + add_); v.momT = 0;
if (window.__ev) window.__ev('MomentumGained', v, null, add_);
floatText(v.x, v.y-26, '氣勢', C.indigo, 18);

merged.to:
a.fragSeq = 0;
if (window.__ev) window.__ev('Merged', a, b, tot);
logEv(`${a.baseLabel} ${b.frag ? '收攏殘部' : '合兵'}，兵 ${Math.round(tot)}`, a.side);

