battle-end.to:
const __gv = grade === '大勝' ? 1 : grade === '小勝' ? 2 : grade === '慘勝' ? 3 : 4;
if (window.__ev) window.__ev('BattleEnded', null, null, __gv);
S.endKind = kind === 'dead' ? 'commander_killed' : kind === 'win' ? 'withdrawn' : kind === 'fled' ? 'commander_fled' : kind === 'rout' ? 'routed' : 'swept';
